/// Shared helpers for the golden-fixture replay tests.
///
/// The fixtures are generated by ref_engine/gen_fixtures.py; these tests
/// prove bit-for-bit parity between the Python reference engine and the
/// Dart port. Any diff here is a port bug, never a fixture bug.
library;

import 'dart:convert';
import 'dart:io';

Map<String, dynamic> loadFixture(String name) =>
    jsonDecode(File('test/fixtures/$name').readAsStringSync())
        as Map<String, dynamic>;

/// Python's sorted([f, n, p]) on [str, int, int] lists.
int fanLineCompare(List a, List b) {
  final c = (a[0] as String).compareTo(b[0] as String);
  if (c != 0) return c;
  final n = (a[1] as int).compareTo(b[1] as int);
  if (n != 0) return n;
  return (a[2] as int).compareTo(b[2] as int);
}

List<List<Object>> sortedFans(Iterable<List> fans) {
  final out = [for (final f in fans) List<Object>.from(f)];
  out.sort(fanLineCompare);
  return out;
}

/// Structural equality over JSON-ish values (Map/List/num/String/bool/null).
bool deepEq(Object? a, Object? b) {
  if (a is Map && b is Map) {
    if (a.length != b.length) return false;
    for (final k in a.keys) {
      if (!b.containsKey(k) || !deepEq(a[k], b[k])) return false;
    }
    return true;
  }
  if (a is List && b is List) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!deepEq(a[i], b[i])) return false;
    }
    return true;
  }
  return a == b;
}

String pretty(Object? v) => const JsonEncoder.withIndent(' ').convert(v);
